\begin{mclaim} \label{mclmpreservation}
  Assume $\mathsf{AD}$ and let $G\subseteq\mathbb{M}_{\aleph_1\aleph_2}$ be $V$-generic.
  Then $\aleph_{\omega+1}$ is regular in $V[G]$.
\end{mclaim}

\begin{claim} \label{clmmeasurables}
  Suppose that $\aleph_0<\kappa<\lambda$ and both $\kappa$ and $\lambda$ are measurable.
  Then ${\rm Gal}(\mathscr{U},\lambda,\lambda)$ holds whenever $\mathscr{U}$ is a normal ultrafilter over $\kappa$.
\end{claim}

\begin{claim} \label{clmpreservation}
  Let $V$ be a model of $\mathsf{AD}$ and let $G\subseteq\mathbb{M}_{\aleph_1\aleph_2}$ be $V$-generic.
  Then $\aleph_1$ is measurable in $V[G]$ and $\mathscr{D}_{\aleph_1}$ is an ultrafilter.
\end{claim}

\begin{claim}
  \label{clmsamecof}
  \begin{enumerate}
    \item [$(a)$] If $\kappa=\cf(\lambda)$ then $\binom{\lambda}{\kappa}\nrightarrow\binom{\lambda}{\kappa}$.
    \item [$(b)$] If ${\rm Gal}(\mathscr{D}_\kappa,\lambda,\lambda)$ holds then $\binom{\lambda}{\kappa}\rightarrow\binom{\lambda}{\kappa}$.
    \item [$(c)$] If $\kappa=\cf(\lambda)$ then $\neg{\rm Gal}(\mathscr{D}_\kappa,\lambda,\lambda)$.
  \end{enumerate}
\end{claim}

\begin{claim}
  \label{clmcorrect} Assume $\mathsf{GCH}$.
  One can force $\mathfrak{gp}=\lambda$ whenever $\lambda>\cf(\lambda)=\omega_1$.
  Moreover, this statement has no consistency strength.
\end{claim}

The forcing $\mathbb{M}_{\gamma\kappa}$. \newline
Let $\kappa$ be regular and uncountable and assume that $\omega\leq\gamma<\kappa$.
\begin{enumerate}
  \item [$(\aleph)$] A condition $p\in\mathbb{M}_{\gamma\kappa}$ is a pair $(s^p,A^p)$ such that $s^p\in[\kappa]^{<\gamma}, A^p\in[\kappa]^\kappa$ and $\bigcup{s^p}<\bigcap{A^p}$.
  \item [$(\beth)$] If $p,q\in\mathbb{M}_{\gamma\kappa}$ then $p\leq{q}$ iff $s^p\subseteq{s^q}, \langle{A^q}\rangle\subseteq\langle{A^p}\rangle$ and $s^q-s^p={}_\omega{t}$ for some $t\in[A]^{<\gamma}$.
\end{enumerate}

\begin{proposition}[ZFC] \label{propfgpstrength}
  The statement $\cf(\mathfrak{fgp})=\omega$ has some consistency strength.
\end{proposition}

\begin{theorem} \label{thmcffgp}
  One can force over a model of $\mathsf{AD}$ to obtain $\mathfrak{fgp}=\aleph_\omega$.
\end{theorem}
